/**
 * Post-build script: Fix wrangler.jsonc generated by OpenNext migration.
 * Removes the broken WORKER_SELF_REFERENCE service binding that points
 * to the old package name "zt" instead of the CF Pages project "zydetect".
 */
const fs = require('fs');
const path = require('path');

const wranglerPath = path.join(__dirname, 'wrangler.jsonc');

if (!fs.existsSync(wranglerPath)) {
  console.log('[postbuild] wrangler.jsonc not found, skipping');
  process.exit(0);
}

try {
  const raw = fs.readFileSync(wranglerPath, 'utf-8');
  // Strip potential comments for JSON parsing
  const cleaned = raw.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '');
  const config = JSON.parse(cleaned);

  // Remove the problematic WORKER_SELF_REFERENCE binding
  if (config.services) {
    config.services = config.services.filter(
      (s) => s.binding !== 'WORKER_SELF_REFERENCE'
    );
  }

  fs.writeFileSync(wranglerPath, JSON.stringify(config, null, 2), 'utf-8');
  console.log('[postbuild] Fixed wrangler.jsonc - removed WORKER_SELF_REFERENCE binding');
} catch (e) {
  console.error('[postbuild] Failed to fix wrangler.jsonc:', e.message);
}
